int foundry_tree_species_find(const char *name) {
  static const char *const names[] = {"acacia", "apple", "baldcypress", "baobab", "birch", "bristlecone", "cedar", "cherry", "coconut", "cypress", "dragonwood", "ebony", "elm", "hickory", "jacaranda", "larch", "lignumvitae", "liveoak", "mahogany", "mango", "mangrove", "maple", "mesquite", "oak", "olive", "osage", "pine", "redwood", "spruce", "teak", "tupelo", "willow"};
  for (int i = 0; name && i < 32; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_tree_age_find(const char *name) {
  static const char *const names[] = {"sapling", "young", "mature", "ancient"};
  for (int i = 0; name && i < 4; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_tree_season_find(const char *name) {
  static const char *const names[] = {"winter", "spring", "summer", "fall"};
  for (int i = 0; name && i < 4; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_tree_detail_find(const char *name) {
  static const char *const names[] = {"high", "medium", "low"};
  for (int i = 0; name && i < 3; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

bool foundry_tree_fruit_applies(foundry_tree_species species) {
  Params p;
  foundry_tree_default_params(&p);
  p.species = species;
  return applies_fruit(p);
}

foundry_status foundry_tree_start_break(foundry_runtime *rt, foundry_instance instance) {
  return foundry_status_of(rt->world.trigger(instance, &kType, 0));
}

foundry_status foundry_tree_get_result(foundry_runtime *rt, foundry_instance instance, foundry_tree_result *out) {
  uint32_t bits = 0;
  const runtime::Status st = rt->world.result(instance, bits);
  if (st != runtime::Status::ok) return foundry_status_of(st);
  if (!out) return FOUNDRY_OK;
  out->break_over = (bits & (1u << 0)) != 0;
  out->ready = (bits & runtime::World::kResultReady) != 0;
  return FOUNDRY_OK;
}

